-- ════════════════════════════════════════════════════════════════════════════════════
-- Load the member extract: raw TSV → stg_extract (as text) → member (typed and cleaned)
-- Run after each new extract. Generated by tools/gen_sql.py (the INSERT lists every column it reads).
-- ════════════════════════════════════════════════════════════════════════════════════
USE ccl;

-- 1. Raw file into staging. Client needs local-infile enabled:
--      singlestore --local-infile -h <host> -u <user> -p ccl < 03_load.sql
--    (In production, a SingleStore PIPELINE from S3 / Azure Blob does the same.)
TRUNCATE TABLE stg_extract;
LOAD DATA LOCAL INFILE 'member_features.tsv'
  INTO TABLE stg_extract
  FIELDS TERMINATED BY '\t'
  LINES TERMINATED BY '\n'
  IGNORE 1 LINES;

-- 2. Typed member rows. The cleaning formulas, per column type:
--      number   CASE WHEN x REGEXP '^-?[0-9]+(\.[0-9]+)?$' THEN CAST(x AS DECIMAL) END      ('NULL', '', text → NULL)
--      date     CASE WHEN x REGEXP '^m/d/yyyy$' THEN STR_TO_DATE(x, '%m/%d/%Y') END
--      money    ' 7,268.55 ' → 7268.55 ; ' -   ' → 0
--      G0       BP 60–260 / 30–160, HbA1c 3–20, eGFR 1–200, UACR 0–5000, BMI 10–80; outside → NULL (999 placeholders, BP 1/1)
INSERT INTO member (member_id, gender, age, nationality, plan_name, policy_group, policy_type, cohort_t2d_l12m, cohort_htn_l12m, t2d_identified_by, htn_identified_by, t2d_category, htn_category, gwp, risk_premium, excluded, p1_complication, p2_recurrent_ed_ip, p3_slipping, p5_newlydiagnosed, p3_offradar, p4_uncontrolled, persona, trig1_hba1c_above_target, trig2a_noaceiarb_kidneyorcad, trig2b_acei_plus_arb, trig2_htn_tx_review, trig3a_hypoglycemia_rev, trig3b_glucagon_not_dispensed, trig3_hypoglycemia_tx, trig4a_nofollowup_post_discharge, trig4b_postdischarge_medsgap, trig4_post_discharge_care, trig5a_kidney_screen_due, trig5b_ckd_monitoring, trig5c_neph_due, trig5_kidney_check, trig6_hba1c_due, trig7_renal_potassium_due, trig8_nutrition_due, trig9_medication_adherence, trig10_new_diagnosis, trig11_annual_labs_due, trig12_eyeexam_due, trig13_highriskfoot_monitor, n_triggers, hba1c_score, clinical_score, comorbid_complication_score, egfr_uacr_points, kidney_score, utilization_score, age_sex_score, total_risk_score, risk_tier, cohort_allocation, priority_clinical_review, last_hba1c_value, last_hba1c_date, last_systolicpressure_value, last_systolicpressure_date, last_diastolicpressure_value, last_measuredbmi_value, last_egfr_value, last_egfr_date, last_fastingplasmaglucose_value, last_hba1c_date2, last_lipid_panel_date, last_urine_albumin_date, last_renal_panel_date, last_egfr_test_date, last_retinal_screen_date, last_liver_function_date, last_cbc_date, last_potassium_date, last_podiatry_visit, last_foot_exam, last_ophthalmology_visit, last_nephrology_visit, last_dietitian_visit, last_diabeducator_visit, first_e11_date, first_htn_date, first_dyslipidemia_date, flag_ckd, dm_complications, dm_complication_count, flag_amputation, flag_dm_hypoglycaemia_last90days, flag_edorip_with_hypoglycaemia_last90days, flag_hypo_hyper_glycemia_last6months, flag_oncology_l12m, flag_oncology_l24m, flag_excl_palliative_hospice_ltc_l12m, flag_dialysis_l12m, flag_excl_transplant_l24m, flag_excl_adv_neuro_congenital_l12m, flag_excl_psych_sud_dementia_l12m, flag_excl_ventilator_tpn_homenursing_l12m, home_nursing_days_l12m, flag_excl_pregnant_postpartum, flag_excl_single_episode_gt60pct, flag_excl_specialty_rx_gt60pct, gp_claims_6m, specialist_claims_6m, last_ip_admit_date, last_ip_discharge_date, second_last_ip_discharge_date, last_ip_facility, last_ip_dx, last_ip_dx_desc, last_ip_drg_desc, last_ip_discharge_type, last_visit_date, first_visit_after_discharge, days_discharge_to_first_visit, flag_no_visit_after_discharge, flag_missing_t2drefill_post_last_discharge, flag_missing_htnrefill_post_last_discharge, last_ed_visit_date, last_ed_facility, last_ed_dx, last_ed_dx_desc, active_drug_class_count, active_drug_classes, flag_active_aceinhibitor, flag_active_arbinhibitor, flag_active_insulin, flag_active_sulfonylurea, flag_overlap_ace_arb_more_than_30days, flag_glucagon_last12months, flag_no_glucagon_last12months, distinct_medicines_90d, t2d_drug_classes_l12m, pdc_metformin, pdc_sglt2, pdc_dpp4, pdc_glp1, pdc_sulfonylurea, pdc_tzd, pdc_any_t2d_noninsulin, latest_new_t2d_class_start_date, last_t2d_fill_date, days_since_t2d_supply_ran_out, flag_t2d_rx_gap_over_30d, htn_drug_classes_l12m, pdc_acei, pdc_arb, pdc_ccb, pdc_beta_blocker, pdc_thiazide, pdc_mra, pdc_any_htn, latest_new_htn_class_start_date, first_ace_arb_mra_thiazide_fill_date, last_htn_fill_date, days_since_htn_supply_ran_out, flag_htn_rx_gap_over_30d, er_visits_6m, ip_admissions_6m, ed_visits_l12m, ip_admissions_l12m, encounters_l12m, encounters_l12m_op, encounters_l12m_ed, encounters_l12m_ip, phg_share_l12m_encounters, last_claim_date, last_claim_costblocks, last_claim_facilities, last_claim_specialties, last_claim_dx_codes, last_claim_dx_desc, last_claim_medicines, last_claim_activities, last_claim_payable, flag_current_smoker_l12m, last_smoking_evidence_date, flag_former_smoker_code, flag_ckd_l12m, flag_kidney_failure_l12m, flag_any_kidney_disease_l12m, flag_stroke_l12m, flag_heart_failure_l12m, flag_mi_l12m, flag_dm_eye_l12m, flag_dm_neuropathy_l12m, flag_dm_circulatory_l12m, flag_dm_foot_l12m, flag_amputation_l12m, flag_dm_hypoglycaemia_l12m, flag_dm_hyperglycaemic_crisis_l12m, flag_ischemic_heart_disease_l12m, flag_dyslipidemia_l12m, flag_obesity, flag_cad_mi_l12m, flag_stroke_tia_l12m, flag_pad_l12m, flag_dm_retinopathy_l12m, flag_peripheral_neuropathy_l12m, flag_dm_foot_ulcer_l12m, flag_major_amputation_l12m, flag_dka_l12m, last_uacr_value, last_uacr_date, ckd_stage_l12m, l12m_payable_diaborhtnrelated, exclusion_nonactiveaccounts, exclusion_op_consultations_encounter, exclusion_alreadyenrolled, initial_target_cohort, l12m_payable_allcause, l12m_payable_diaborhtnrelated_inside, l12m_payable_diaborhtnrelated_outside, language, has_t2d, has_htn)
SELECT   CASE WHEN TRIM(s.`mask_id`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`mask_id`) END AS member_id,
  CASE WHEN TRIM(s.`GENDER`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`GENDER`) END AS gender,
  CASE WHEN TRIM(s.`AGE`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`AGE`) AS DECIMAL(14,4)) END AS age,
  CASE WHEN TRIM(s.`NATIONALITY`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`NATIONALITY`) END AS nationality,
  CASE WHEN TRIM(s.`plan_name`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`plan_name`) END AS plan_name,
  CASE WHEN TRIM(s.`policy_group`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`policy_group`) END AS policy_group,
  CASE WHEN TRIM(s.`policy_type`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`policy_type`) END AS policy_type,
  CASE WHEN TRIM(s.`cohort_t2d_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`cohort_t2d_l12m`) AS DECIMAL(14,4)) END AS cohort_t2d_l12m,
  CASE WHEN TRIM(s.`cohort_htn_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`cohort_htn_l12m`) AS DECIMAL(14,4)) END AS cohort_htn_l12m,
  CASE WHEN TRIM(s.`t2d_identified_by`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`t2d_identified_by`) END AS t2d_identified_by,
  CASE WHEN TRIM(s.`htn_identified_by`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`htn_identified_by`) END AS htn_identified_by,
  CASE WHEN TRIM(s.`t2d_category`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`t2d_category`) END AS t2d_category,
  CASE WHEN TRIM(s.`htn_category`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`htn_category`) END AS htn_category,
  CASE WHEN TRIM(s.`GWP`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`GWP`) AS DECIMAL(14,4)) END AS gwp,
  CASE WHEN TRIM(s.`Risk Premium`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Risk Premium`) AS DECIMAL(14,4)) END AS risk_premium,
  CASE WHEN TRIM(s.`Exclusion`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Exclusion`) AS DECIMAL(14,4)) END AS excluded,
  CASE WHEN TRIM(s.`P1_Complication`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P1_Complication`) AS DECIMAL(14,4)) END AS p1_complication,
  CASE WHEN TRIM(s.`P2_Recurrent_ED_IP`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P2_Recurrent_ED_IP`) AS DECIMAL(14,4)) END AS p2_recurrent_ed_ip,
  CASE WHEN TRIM(s.`P3_slipping`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P3_slipping`) AS DECIMAL(14,4)) END AS p3_slipping,
  CASE WHEN TRIM(s.`P5_newlydiagnosed`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P5_newlydiagnosed`) AS DECIMAL(14,4)) END AS p5_newlydiagnosed,
  CASE WHEN TRIM(s.`P3_offradar`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P3_offradar`) AS DECIMAL(14,4)) END AS p3_offradar,
  CASE WHEN TRIM(s.`P4_uncontrolled`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`P4_uncontrolled`) AS DECIMAL(14,4)) END AS p4_uncontrolled,
  CASE WHEN TRIM(s.`Persona`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`Persona`) END AS persona,
  CASE WHEN TRIM(s.`Trig1_HbA1c_above_target`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig1_HbA1c_above_target`) AS DECIMAL(14,4)) END AS trig1_hba1c_above_target,
  CASE WHEN TRIM(s.`Trig2a_NoACEiARB_KidneyOrCAD`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig2a_NoACEiARB_KidneyOrCAD`) AS DECIMAL(14,4)) END AS trig2a_noaceiarb_kidneyorcad,
  CASE WHEN TRIM(s.`Trig2b_ACEi_plus_ARB`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig2b_ACEi_plus_ARB`) AS DECIMAL(14,4)) END AS trig2b_acei_plus_arb,
  CASE WHEN TRIM(s.`Trig2_HTN_tx_review`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig2_HTN_tx_review`) AS DECIMAL(14,4)) END AS trig2_htn_tx_review,
  CASE WHEN TRIM(s.`Trig3a_hypoglycemia_rev`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig3a_hypoglycemia_rev`) AS DECIMAL(14,4)) END AS trig3a_hypoglycemia_rev,
  CASE WHEN TRIM(s.`Trig3b_glucagon_not_dispensed`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig3b_glucagon_not_dispensed`) AS DECIMAL(14,4)) END AS trig3b_glucagon_not_dispensed,
  CASE WHEN TRIM(s.`Trig3_hypoglycemia_tx`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig3_hypoglycemia_tx`) AS DECIMAL(14,4)) END AS trig3_hypoglycemia_tx,
  CASE WHEN TRIM(s.`Trig4a_NoFollowup_post_discharge`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig4a_NoFollowup_post_discharge`) AS DECIMAL(14,4)) END AS trig4a_nofollowup_post_discharge,
  CASE WHEN TRIM(s.`Trig4b_postdischarge_medsgap`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig4b_postdischarge_medsgap`) AS DECIMAL(14,4)) END AS trig4b_postdischarge_medsgap,
  CASE WHEN TRIM(s.`Trig4_post_discharge_care`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig4_post_discharge_care`) AS DECIMAL(14,4)) END AS trig4_post_discharge_care,
  CASE WHEN TRIM(s.`Trig5a_Kidney_screen_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig5a_Kidney_screen_due`) AS DECIMAL(14,4)) END AS trig5a_kidney_screen_due,
  CASE WHEN TRIM(s.`Trig5b_CKD_monitoring`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig5b_CKD_monitoring`) AS DECIMAL(14,4)) END AS trig5b_ckd_monitoring,
  CASE WHEN TRIM(s.`Trig5c_Neph_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig5c_Neph_due`) AS DECIMAL(14,4)) END AS trig5c_neph_due,
  CASE WHEN TRIM(s.`Trig5_Kidney_check`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig5_Kidney_check`) AS DECIMAL(14,4)) END AS trig5_kidney_check,
  CASE WHEN TRIM(s.`Trig6_HbA1c_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig6_HbA1c_due`) AS DECIMAL(14,4)) END AS trig6_hba1c_due,
  CASE WHEN TRIM(s.`Trig7_Renal_Potassium_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig7_Renal_Potassium_due`) AS DECIMAL(14,4)) END AS trig7_renal_potassium_due,
  CASE WHEN TRIM(s.`Trig8_nutrition_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig8_nutrition_due`) AS DECIMAL(14,4)) END AS trig8_nutrition_due,
  CASE WHEN TRIM(s.`Trig9_medication_adherence`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig9_medication_adherence`) AS DECIMAL(14,4)) END AS trig9_medication_adherence,
  CASE WHEN TRIM(s.`Trig10_new_diagnosis`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig10_new_diagnosis`) AS DECIMAL(14,4)) END AS trig10_new_diagnosis,
  CASE WHEN TRIM(s.`Trig11_annual_labs_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig11_annual_labs_due`) AS DECIMAL(14,4)) END AS trig11_annual_labs_due,
  CASE WHEN TRIM(s.`Trig12_eyeexam_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig12_eyeexam_due`) AS DECIMAL(14,4)) END AS trig12_eyeexam_due,
  CASE WHEN TRIM(s.`Trig13_highriskfoot_monitor`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig13_highriskfoot_monitor`) AS DECIMAL(14,4)) END AS trig13_highriskfoot_monitor,
  CASE WHEN TRIM(s.`# of triggers`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`# of triggers`) AS DECIMAL(14,4)) END AS n_triggers,
  CASE WHEN TRIM(s.`HbA1c_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`HbA1c_score`) AS DECIMAL(14,4)) END AS hba1c_score,
  CASE WHEN TRIM(s.`Clinical_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Clinical_score`) AS DECIMAL(14,4)) END AS clinical_score,
  CASE WHEN TRIM(s.`Comorbid_complication_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Comorbid_complication_score`) AS DECIMAL(14,4)) END AS comorbid_complication_score,
  CASE WHEN TRIM(s.`eGFR + UACR points`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`eGFR + UACR points`) AS DECIMAL(14,4)) END AS egfr_uacr_points,
  CASE WHEN TRIM(s.`Kidney_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Kidney_score`) AS DECIMAL(14,4)) END AS kidney_score,
  CASE WHEN TRIM(s.`Utilization_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Utilization_score`) AS DECIMAL(14,4)) END AS utilization_score,
  CASE WHEN TRIM(s.`Age_sex_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Age_sex_score`) AS DECIMAL(14,4)) END AS age_sex_score,
  CASE WHEN TRIM(s.`Total_risk_Score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Total_risk_Score`) AS DECIMAL(14,4)) END AS total_risk_score,
  CASE WHEN TRIM(s.`Risk_tier`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`Risk_tier`) END AS risk_tier,
  CASE WHEN TRIM(s.`Cohort_allocation`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`Cohort_allocation`) END AS cohort_allocation,
  CASE WHEN TRIM(s.`Priority_clinical_review`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Priority_clinical_review`) AS DECIMAL(14,4)) END AS priority_clinical_review,
  CASE WHEN (CASE WHEN TRIM(s.`Last_HbA1c_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_HbA1c_Value`) AS DECIMAL(14,4)) END) BETWEEN 3.0 AND 20.0 THEN (CASE WHEN TRIM(s.`Last_HbA1c_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_HbA1c_Value`) AS DECIMAL(14,4)) END) END AS last_hba1c_value,
  CASE WHEN TRIM(s.`Last_HbA1c_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_HbA1c_Date`), '%m/%d/%Y') END AS last_hba1c_date,
  CASE WHEN (CASE WHEN TRIM(s.`Last_SystolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_SystolicPressure_Value`) AS DECIMAL(14,4)) END) BETWEEN 60.0 AND 260.0 THEN (CASE WHEN TRIM(s.`Last_SystolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_SystolicPressure_Value`) AS DECIMAL(14,4)) END) END AS last_systolicpressure_value,
  CASE WHEN TRIM(s.`Last_SystolicPressure_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_SystolicPressure_Date`), '%m/%d/%Y') END AS last_systolicpressure_date,
  CASE WHEN (CASE WHEN TRIM(s.`Last_DiastolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_DiastolicPressure_Value`) AS DECIMAL(14,4)) END) BETWEEN 30.0 AND 160.0 THEN (CASE WHEN TRIM(s.`Last_DiastolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_DiastolicPressure_Value`) AS DECIMAL(14,4)) END) END AS last_diastolicpressure_value,
  CASE WHEN (CASE WHEN TRIM(s.`Last_MeasuredBMI_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_MeasuredBMI_Value`) AS DECIMAL(14,4)) END) BETWEEN 10.0 AND 80.0 THEN (CASE WHEN TRIM(s.`Last_MeasuredBMI_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_MeasuredBMI_Value`) AS DECIMAL(14,4)) END) END AS last_measuredbmi_value,
  CASE WHEN (CASE WHEN TRIM(s.`Last_eGFR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_eGFR_Value`) AS DECIMAL(14,4)) END) BETWEEN 1.0 AND 200.0 THEN (CASE WHEN TRIM(s.`Last_eGFR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_eGFR_Value`) AS DECIMAL(14,4)) END) END AS last_egfr_value,
  CASE WHEN TRIM(s.`Last_eGFR_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_eGFR_Date`), '%m/%d/%Y') END AS last_egfr_date,
  CASE WHEN TRIM(s.`last_fastingplasmaglucose_value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`last_fastingplasmaglucose_value`) AS DECIMAL(14,4)) END AS last_fastingplasmaglucose_value,
  CASE WHEN TRIM(s.`last_hba1c_date2`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_hba1c_date2`), '%m/%d/%Y') END AS last_hba1c_date2,
  CASE WHEN TRIM(s.`last_lipid_panel_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_lipid_panel_date`), '%m/%d/%Y') END AS last_lipid_panel_date,
  CASE WHEN TRIM(s.`last_urine_albumin_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_urine_albumin_date`), '%m/%d/%Y') END AS last_urine_albumin_date,
  CASE WHEN TRIM(s.`last_renal_panel_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_renal_panel_date`), '%m/%d/%Y') END AS last_renal_panel_date,
